import sys

def max_valid_instructions(s):
    moves = {'L': -1, 'R': 1, 'U': 1j, 'D': -1j}
    net_displacement = 0
    for c in s:
        net_displacement += moves[c]
    if net_displacement != 0:
        return 0

    count = {}
    for c in s:
        count[c] = count.get(c, 0) + 1
        if count[c] > 2:
            return len(s)

    L = R = U = D = 0
    for c in s:
        if c == 'L':
            L += 1
        elif c == 'R':
            R += 1
        elif c == 'U':
            U += 1
        else:
            D += 1

    min_moves = float('inf')
    for l in range(L + 1):
        r = L - l
        u = (L + R) // 2 - l
        d = (L + R) // 2 - r
