        line = line.center(width, ' ')
        result.append(line)
    for i in reversed(range(n - 1)):
        line = '1'
        for j in range(1, n - i):
            line += str(j)
        for j in reversed(range(1, n - i)):
            line += str(j)
        line = line.center(width, ' ')
        result.append(line)
    return '\n'.join(result)

