def count_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    same = k
    diff = k * (k - 1)
    for _ in range(3, n + 1):
        temp = diff
        diff = (same + diff) * (k - 1)
        same = temp
    return same + diff

